            set propagation_phase(val: PropagationPhase);
            /**
             * The propagation phase at which this controller will handle events.
             */
            get propagationPhase(): PropagationPhase;
            set propagationPhase(val: PropagationPhase);
            /**
             * The widget receiving the #GdkEvents that the controller will handle.
             */
            get widget(): Widget;

            // Constructors

            constructor(properties?: Partial<EventController.ConstructorProps>, ...args: any[]);

            _init(...args: any[]): void;

            // Methods

            /**
             * Gets the propagation phase at which `controller` handles events.
             * @returns the propagation phase
             */
            get_propagation_phase(): PropagationPhase;
            /**
             * Returns the #GtkWidget this controller relates to.
             * @returns a #GtkWidget
             */
            get_widget(): Widget;
            /**
             * Feeds an events into `controller,` so it can be interpreted
             * and the controller actions triggered.
             * @param event a #GdkEvent
             * @returns %TRUE if the event was potentially useful to trigger the          controller action
             */
            handle_event(event: Gdk.Event): boolean;
            /**
             * Resets the `controller` to a clean state. Every interaction
             * the controller did through #GtkEventController::handle-event
             * will be dropped at this point.
             */
